  storage_path text,
  description text,
  created_at timestamp with time zone NOT NULL DEFAULT now()
);

alter table public.dispute_evidence enable row level security;

alter table dispute_evidence add constraint dispute_evidence_dispute_id_fkey FOREIGN KEY (dispute_id) REFERENCES disputes(id) ON DELETE CASCADE;
alter table dispute_evidence add constraint dispute_evidence_pkey PRIMARY KEY (id);
alter table dispute_evidence add constraint dispute_evidence_uploaded_by_fkey FOREIGN KEY (uploaded_by) REFERENCES auth.users(id);

create policy dispute_evidence_select_combined on public.dispute_evidence for SELECT to public using (((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND profiles.is_admin))) OR (EXISTS ( SELECT 1
   FROM (disputes d
     JOIN orders o ON ((o.id = d.order_id)))
  WHERE ((d.id = dispute_evidence.dispute_id) AND ((o.buyer_id = ( SELECT auth.uid() AS uid)) OR (o.seller_id = ( SELECT auth.uid() AS uid))))))));
create policy evidence_insert_participant on public.dispute_evidence for INSERT to public with check (((( SELECT auth.uid() AS uid) = uploaded_by) AND (EXISTS ( SELECT 1
   FROM (disputes d
     JOIN orders o ON ((o.id = d.order_id)))
  WHERE ((d.id = dispute_evidence.dispute_id) AND ((o.buyer_id = ( SELECT auth.uid() AS uid)) OR (o.seller_id = ( SELECT auth.uid() AS uid))) AND (d.status = ANY (ARRAY['open'::dispute_status, 'under_review'::dispute_status])))))));


