alter table dispute_messages add constraint dispute_messages_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES profiles(id);

create policy dispute_messages_insert_combined on public.dispute_messages for INSERT to public with check ((((( SELECT auth.uid() AS uid) = sender_id) AND (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND profiles.is_admin))) AND (EXISTS ( SELECT 1
   FROM disputes d
  WHERE ((d.id = dispute_messages.dispute_id) AND (d.status = ANY (ARRAY['open'::dispute_status, 'under_review'::dispute_status])))))) OR ((( SELECT auth.uid() AS uid) = sender_id) AND (EXISTS ( SELECT 1
   FROM (disputes d
     JOIN orders o ON ((o.id = d.order_id)))
  WHERE ((d.id = dispute_messages.dispute_id) AND ((o.buyer_id = ( SELECT auth.uid() AS uid)) OR (o.seller_id = ( SELECT auth.uid() AS uid))) AND (d.status = ANY (ARRAY['open'::dispute_status, 'under_review'::dispute_status]))))))));
create policy dispute_messages_select_combined on public.dispute_messages for SELECT to public using (((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND profiles.is_admin))) OR (EXISTS ( SELECT 1
   FROM (disputes d
     JOIN orders o ON ((o.id = d.order_id)))
  WHERE ((d.id = dispute_messages.dispute_id) AND ((o.buyer_id = ( SELECT auth.uid() AS uid)) OR (o.seller_id = ( SELECT auth.uid() AS uid))))))));


