create table if not exists public.disputes (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL,
  opened_by uuid NOT NULL,
  reason text NOT NULL,
  status dispute_status NOT NULL DEFAULT 'open'::dispute_status,
  admin_note text,
  resolved_by uuid,
  resolved_at timestamp with time zone,
  split_refund_pct numeric,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  buyer_offer_pct numeric,
  offer_status text NOT NULL DEFAULT 'none'::text,
  return_stage text NOT NULL DEFAULT 'none'::text,
  return_tracking_number text,
  return_shipping_cost_mdl numeric,
  return_shipped_at timestamp with time zone,
  return_received_at timestamp with time zone
);

alter table public.disputes enable row level security;

alter table disputes add constraint disputes_buyer_offer_pct_check CHECK (((buyer_offer_pct IS NULL) OR ((buyer_offer_pct >= (0)::numeric) AND (buyer_offer_pct <= (100)::numeric))));
alter table disputes add constraint disputes_offer_status_check CHECK ((offer_status = ANY (ARRAY['none'::text, 'pending'::text, 'accepted'::text, 'rejected'::text])));
alter table disputes add constraint disputes_opened_by_fkey FOREIGN KEY (opened_by) REFERENCES auth.users(id);
alter table disputes add constraint disputes_order_id_fkey FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE;
alter table disputes add constraint disputes_order_id_key UNIQUE (order_id);
alter table disputes add constraint disputes_pkey PRIMARY KEY (id);
alter table disputes add constraint disputes_resolved_by_fkey FOREIGN KEY (resolved_by) REFERENCES auth.users(id);
alter table disputes add constraint disputes_return_shipping_cost_mdl_check CHECK (((return_shipping_cost_mdl IS NULL) OR (return_shipping_cost_mdl >= (0)::numeric)));
alter table disputes add constraint disputes_return_stage_check CHECK ((return_stage = ANY (ARRAY['none'::text, 'awaiting_return'::text, 'shipped'::text, 'received'::text])));

CREATE INDEX idx_disputes_order ON public.disputes USING btree (order_id);

create policy disputes_insert_buyer on public.disputes for INSERT to public with check (((( SELECT auth.uid() AS uid) = opened_by) AND (EXISTS ( SELECT 1
   FROM orders o
  WHERE ((o.id = disputes.order_id) AND (o.buyer_id = ( SELECT auth.uid() AS uid)) AND (o.status = 'shipped'::order_status))))));
create policy disputes_select_combined on public.disputes for SELECT to public using (((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND profiles.is_admin))) OR (EXISTS ( SELECT 1
   FROM orders o
  WHERE ((o.id = disputes.order_id) AND ((o.buyer_id = ( SELECT auth.uid() AS uid)) OR (o.seller_id = ( SELECT auth.uid() AS uid))))))));
create policy disputes_update_combined on public.disputes for UPDATE to public using ((((( SELECT auth.uid() AS uid) = opened_by) AND (status = 'open'::dispute_status)) OR ((( SELECT auth.uid() AS uid) = opened_by) AND (return_stage = 'awaiting_return'::text)) OR ((EXISTS ( SELECT 1
   FROM orders o
  WHERE ((o.id = disputes.order_id) AND (o.seller_id = ( SELECT auth.uid() AS uid))))) AND (offer_status = 'pending'::text)))) with check ((((( SELECT auth.uid() AS uid) = opened_by) AND (status = 'open'::dispute_status) AND (offer_status = 'pending'::text)) OR ((( SELECT auth.uid() AS uid) = opened_by) AND (return_stage = 'shipped'::text) AND (return_tracking_number IS NOT NULL) AND (return_shipping_cost_mdl IS NOT NULL)) OR ((offer_status = 'rejected'::text) AND (status = 'under_review'::dispute_status))));


