   FROM conversations c
  WHERE ((c.id = messages.conversation_id) AND ((c.buyer_id = ( SELECT auth.uid() AS uid)) OR (c.seller_id = ( SELECT auth.uid() AS uid)))))) OR (( SELECT auth.uid() AS uid) = sender_id))) with check (((( SELECT auth.uid() AS uid) <> sender_id) OR (( SELECT auth.uid() AS uid) = sender_id)));


