create table if not exists public.orders (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  buyer_id uuid NOT NULL,
  seller_id uuid NOT NULL,
  item_id bigint NOT NULL,
  status order_status NOT NULL DEFAULT 'pending_payment'::order_status,
  price_mdl numeric NOT NULL,
  fee_pct numeric NOT NULL DEFAULT 0,
  fee_mdl numeric NOT NULL DEFAULT 0,
  net_mdl numeric NOT NULL,
  stripe_payment_intent_id text,
  stripe_charge_id text,
  stripe_transfer_id text,
  stripe_refund_id text,
  shipping_address jsonb,
  courier_name text,
  tracking_number text,
  paid_at timestamp with time zone,
  shipped_at timestamp with time zone,
  delivered_at timestamp with time zone,
  completed_at timestamp with time zone,
  cancelled_at timestamp with time zone,
  auto_release_at timestamp with time zone,
  scheduled_delete_at timestamp with time zone,
  has_open_ticket boolean NOT NULL DEFAULT false,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now()
);

alter table public.orders enable row level security;

alter table orders add constraint buyer_ne_seller CHECK ((buyer_id <> seller_id));
alter table orders add constraint net_lte_price CHECK ((net_mdl <= price_mdl));
alter table orders add constraint orders_buyer_id_fkey FOREIGN KEY (buyer_id) REFERENCES auth.users(id);
alter table orders add constraint orders_fee_mdl_check CHECK ((fee_mdl >= (0)::numeric));
alter table orders add constraint orders_fee_pct_check CHECK ((fee_pct >= (0)::numeric));
alter table orders add constraint orders_item_id_fkey FOREIGN KEY (item_id) REFERENCES items(id);
alter table orders add constraint orders_net_mdl_check CHECK ((net_mdl >= (0)::numeric));
alter table orders add constraint orders_pkey PRIMARY KEY (id);
alter table orders add constraint orders_price_mdl_check CHECK ((price_mdl > (0)::numeric));
alter table orders add constraint orders_seller_id_fkey FOREIGN KEY (seller_id) REFERENCES auth.users(id);
alter table orders add constraint orders_stripe_payment_intent_id_key UNIQUE (stripe_payment_intent_id);

CREATE INDEX idx_orders_auto_release ON public.orders USING btree (auto_release_at) WHERE (status = 'shipped'::order_status);
CREATE INDEX idx_orders_buyer ON public.orders USING btree (buyer_id);
CREATE INDEX idx_orders_cleanup ON public.orders USING btree (scheduled_delete_at) WHERE (status = ANY (ARRAY['completed'::order_status, 'refunded'::order_status, 'cancelled'::order_status]));
CREATE INDEX idx_orders_item ON public.orders USING btree (item_id);
CREATE INDEX idx_orders_seller ON public.orders USING btree (seller_id);
CREATE INDEX idx_orders_status ON public.orders USING btree (status);
CREATE INDEX idx_orders_stripe_pi ON public.orders USING btree (stripe_payment_intent_id) WHERE (stripe_payment_intent_id IS NOT NULL);

create policy orders_insert_buyer on public.orders for INSERT to public with check ((( SELECT auth.uid() AS uid) = buyer_id));
create policy orders_select_combined on public.orders for SELECT to public using (((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND profiles.is_admin))) OR ((( SELECT auth.uid() AS uid) = buyer_id) OR (( SELECT auth.uid() AS uid) = seller_id))));
create policy orders_update_combined on public.orders for UPDATE to public using ((((( SELECT auth.uid() AS uid) = buyer_id) AND (status = 'shipped'::order_status)) OR ((( SELECT auth.uid() AS uid) = seller_id) AND (status = 'paid'::order_status)))) with check (((status = ANY (ARRAY['delivered'::order_status, 'disputed'::order_status])) OR ((status = 'shipped'::order_status) AND (tracking_number IS NOT NULL) AND (courier_name IS NOT NULL))));


