alter table withdrawal_requests add constraint withdrawal_requests_pkey PRIMARY KEY (id);
alter table withdrawal_requests add constraint withdrawal_requests_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

CREATE INDEX withdrawal_requests_user_id_idx ON public.withdrawal_requests USING btree (user_id);

create policy withdrawal_requests_insert_owner on public.withdrawal_requests for INSERT to public with check ((( SELECT auth.uid() AS uid) = user_id));
create policy withdrawal_requests_select_admin on public.withdrawal_requests for SELECT to public using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND profiles.is_admin))));
create policy withdrawal_requests_select_owner on public.withdrawal_requests for SELECT to public using ((( SELECT auth.uid() AS uid) = user_id));
create policy withdrawal_requests_update_admin on public.withdrawal_requests for UPDATE to public using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND profiles.is_admin)))) with check ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND profiles.is_admin))));


-- ============================================
-- FUNCTIONS
-- ============================================

CREATE OR REPLACE FUNCTION public.cleanup_expired_conversations()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Șterge mesajele din conversațiile expirate (fără ticket deschis)
  DELETE FROM messages
  WHERE conversation_id IN (
    SELECT id FROM conversations
    WHERE scheduled_delete_at IS NOT NULL
      AND scheduled_delete_at <= NOW()
      AND has_open_ticket = FALSE  
  );

  -- Șterge conversațiile expirate
  DELETE FROM conversations
  WHERE scheduled_delete_at IS NOT NULL
    AND scheduled_delete_at <= NOW()
    AND has_open_ticket = FALSE;
    
  RAISE LOG 'cleanup_expired_conversations: rulat la %', NOW();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_profile_on_signup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO profiles (id, username)
  VALUES (
    NEW.id,
    COALESCE(
      NEW.raw_user_meta_data ->> 'username',
      split_part(NEW.email, '@', 1)
    )
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_single_default_address()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_default = true THEN
    UPDATE shipping_addresses
    SET is_default = false
    WHERE user_id = NEW.user_id AND id != NEW.id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.orders_status_timestamps()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'paid'      AND OLD.status != 'paid'      THEN
    NEW.paid_at = now();
  END IF;
  IF NEW.status = 'shipped'   AND OLD.status != 'shipped'   THEN
    NEW.shipped_at      = now();
    NEW.auto_release_at = now() + INTERVAL '14 days';
  END IF;
  IF NEW.status = 'delivered' AND OLD.status != 'delivered' THEN
    NEW.delivered_at = now();
  END IF;
  IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
    NEW.completed_at        = now();
    NEW.scheduled_delete_at = now() + INTERVAL '7 days';
  END IF;
  IF NEW.status IN ('cancelled','refunded')
     AND OLD.status NOT IN ('cancelled','refunded') THEN
    NEW.cancelled_at        = now();
    NEW.scheduled_delete_at = now() + INTERVAL '7 days';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_scheduled_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.completed_at IS NOT NULL AND OLD.completed_at IS NULL THEN
    NEW.scheduled_delete_at := NEW.completed_at + INTERVAL '7 days';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_item_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'paid' AND OLD.status = 'pending_payment' THEN
    UPDATE public.items SET status = 'reserved' WHERE id = NEW.item_id;

  ELSIF NEW.status = 'completed' THEN
    UPDATE public.items SET status = 'sold'     WHERE id = NEW.item_id;

  ELSIF NEW.status IN ('refunded','cancelled')
        AND OLD.status NOT IN ('refunded','cancelled') THEN
    UPDATE public.items SET status = 'active'   WHERE id = NEW.item_id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_open_ticket_flag()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE orders SET has_open_ticket = true,  status = 'disputed'
    WHERE id = NEW.order_id;
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.status IN ('resolved_release','resolved_refund','resolved_split','closed')
     AND OLD.status NOT IN ('resolved_release','resolved_refund','resolved_split','closed') THEN
    UPDATE orders SET has_open_ticket = false WHERE id = NEW.order_id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_conversation_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE conversations
  SET updated_at = now()
  WHERE id = NEW.conversation_id;
  RETURN NEW;
END;
$function$
;